function mech15DecibelLived() {
  const f = state.save.storyFlags || (state.save.storyFlags = {});
  if (f.decibel_lived_beat_done) return;
  const vol = f.quest_volume_active || f.quest_volume_accepted || f.natural_volume_street
    || document.body.classList.contains('rp-cold-yielded');
  const prop = document.querySelector('[data-testid=story-street-headphones-note], .rp-stage-prop--headphones-note');
  if (!vol || !prop) return;

  const fire = (choice) => {
    if (f.decibel_lived_beat_done) return;
    f.decibel_lived_beat_done = true;
    prop.classList.add('rp-prop--decibel-lived', 'is-reacting');
    prop.dataset.decibelLivedBeat = '1';
    prop.dataset.decibelReaction = 'headphones-bass';
    prop.setAttribute('data-testid', prop.getAttribute('data-testid') || 'decibel-lived-prop');
    spawnFloat?.({ text: 'Bass sticks — Peri hears it', ms: 1400, anchor: prop });
    shakeOnce?.(prop, 420);
    const pick = choice || 'peri_quiet';
    if (pick === 'orhan_volume') {
      f.decibel_lived_orhan_volume = true;
      bumpAffinity?.('n4', 4); bumpAffinity?.('n5', 2);
      queueCupMod?.({ unitId: 'n4', modId: 'mod_orhan_volume_yield' });
    } else {
      f.decibel_lived_peri_quiet = true;
      f.secret_peri_offer_tease = true;
      bumpAffinity?.('n5', 6);
      queueCupMod?.({ unitId: 'n5', modId: 'mod_peri_quiet_set_preview' });
    }
    window.__RP_SMOKE__ = Object.assign(window.__RP_SMOKE__ || {}, {
      decibelLived: { beat: true, choice: pick, periQuiet: !!f.decibel_lived_peri_quiet, orhanVolume: !!f.decibel_lived_orhan_volume }
    });
    try { localStorage.setItem('rp_smoke_decibel_lived', JSON.stringify(window.__RP_SMOKE__.decibelLived)); } catch {}
    hideChips?.();
  };

  // coach pulse — non-blocking
  prop.classList.add('rp-prop--decibel-cue');
  showGhostChips?.({
    testId: 'decibel-lived-choice',
    options: [
      { id: 'peri_quiet', label: 'Quiet cans for Peri' },
      { id: 'orhan_volume', label: 'Orhan turns it down' }
    ],
    onPick: fire,
    timeoutMs: 3500,
    defaultId: 'peri_quiet'
  });
  prop.addEventListener('click', () => fire(state._decibelChip || 'peri_quiet'), { once: true });
  setTimeout(() => fire('peri_quiet'), 4000); // soft-fallback — never stalls street
}

// Call from renderStreet AFTER volume_natural / Open Volume path. Do NOT call from fight tick.

cssAppend:
/* mechanics-fix-15 — Decibel lived prop; non-blocking */
.rp-stage-prop--headphones-note.rp-prop--decibel-cue {
  outline: 2px solid rgba(80, 220, 200, 0.55);
  animation: rp-decibel-pulse 1.1s ease-in-out 2;
}
.rp-stage-prop--headphones-note.rp-prop--decibel-lived.is-reacting {
  transform-origin: center;
  animation: rp-decibel-shake 0.42s ease-out 1;
}
@keyframes rp-decibel-pulse {
  0%, 100% { filter: brightness(1); }
  50% { filter: brightness(1.25); }
}
@keyframes rp-decibel-shake {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-3px) rotate(-1deg); }
  75% { transform: translateX(3px) rotate(1deg); }
}
[data-testid="decibel-lived-choice"] {
  pointer-events: auto;
  z-index: 4;
}
/* never cover End evening / Volume CTAs */
[data-testid="decibel-lived-choice"] {
  max-width: min(92vw, 320px);
  margin: 0.35rem auto 0;
}
